            parts.append((0, int(text), ""))
        else:
            parts.append((1, 0, text.lower()))
    return tuple(parts)


def _pad(values, width):
    values = tuple(values)
    return values + (0,) * (width - len(values))


def _compare_numbers(left, right):
    """逐段按十进制整数比较两组版本段，短的一组按 0 补齐。"""
    left = tuple(left)
    right = tuple(right)
    width = max(len(left), len(right))
    left, right = _pad(left, width), _pad(right, width)
    if left == right:
        return 0
    return 1 if left > right else -1


def _compare_prerelease(left, right):
    """比较预发布标签：正式版（空标签）高于任何预发布版。"""
    left = str(left or "").strip()
    right = str(right or "").strip()
    if left == right:
        return 0
    if not left:
        return 1
    if not right:
        return -1
    left_key, right_key = _prerelease_key(left), _prerelease_key(right)
    if left_key == right_key:
        return 0
    return 1 if left_key > right_key else -1


class VersionTuple(tuple):
    """:func:`parse_version` 的结果：四段十进制整数组成的元组（不足补 0）。

    它**就是**一个 ``tuple``，所以::

        parse_version("1.2") == (1, 2, 0, 0)
        list(parse_version("1.2")) == [1, 2, 0, 0]
        parse_version("1.10.0") > parse_version("1.9.0")

    都成立。与普通 ``list`` / ``tuple`` 比较时只看数字段（位数不同按 0 补齐）；
    两个 :class:`VersionTuple` 之间比较时，数字段相同则再看预发布标签，
    带标签的版本低于同号的正式版。
    """

    __slots__ = ("prerelease",)

    def __new__(cls, segments=(), prerelease=""):
        self = tuple.__new__(cls, (segment_value(value) for value in segments))
        self.prerelease = str(prerelease or "").strip()
        return self

    def _parts_of(self, other):
        """把 ``other`` 拆成 ``(数字段, 预发布标签, 是否带标签信息)``。"""
        if isinstance(other, VersionTuple):
            return tuple(other), other.prerelease, True
        if isinstance(other, (list, tuple)):
            return tuple(segment_value(value) for value in other), "", False
        return None

    def compare(self, other):
        """返回 ``-1`` / ``0`` / ``1``；``other`` 不可比较时返回 ``None``。"""
        parts = self._parts_of(other)
        if parts is None:
            return None
        numbers, prerelease, tagged = parts
        result = _compare_numbers(tuple(self), numbers)
        if result or not tagged:
            return result
        return _compare_prerelease(self.prerelease, prerelease)

    def __eq__(self, other):
        result = self.compare(other)
        return NotImplemented if result is None else result == 0

    def __ne__(self, other):
        result = self.compare(other)
        return NotImplemented if result is None else result != 0

    def __lt__(self, other):
        result = self.compare(other)
        return NotImplemented if result is None else result < 0

    def __le__(self, other):
        result = self.compare(other)
        return NotImplemented if result is None else result <= 0

    def __gt__(self, other):
        result = self.compare(other)
        return NotImplemented if result is None else result > 0

    def __ge__(self, other):
        result = self.compare(other)
        return NotImplemented if result is None else result >= 0

    def __hash__(self):
        return tuple.__hash__(self)

    def __repr__(self):
        text = "(%s%s)" % (
            ", ".join(str(part) for part in self),
            "," if len(self) == 1 else "",
        )
        if self.prerelease:
            return "%s  # prerelease=%r" % (text, self.prerelease)
        return text

    def padded(self, width=SEGMENTS):
        """补齐到 ``width`` 段，返回新的 :class:`VersionTuple`。"""
        return VersionTuple(numeric_segments(self, width), self.prerelease)


def parse_version(text):
    """把版本号解析成四段十进制整数（不足四段在末尾补 0）。

    返回 :class:`VersionTuple`（``tuple`` 子类），另外带上 ``prerelease``
    属性::

        parse_version("1.2")         == (1, 2, 0, 0)
        parse_version("1.10.0")[1]   == 10
        parse_version("1.0.0-beta").prerelease == "beta"
    """
    if isinstance(text, VersionTuple):
        return text
    numbers, prerelease = split_version(text)
    return VersionTuple(numeric_segments(numbers), prerelease)


def compare_versions(left, right):
    """比较两个版本号。

    返回 ``-1`` / ``0`` / ``1``。逐段按十进制整数比较，不足四段补 0；
    数字部分相同时，预发布版本低于同号的正式版。
    """
    left_version = parse_version(left)
    right_version = parse_version(right)
    result = _compare_numbers(tuple(left_version), tuple(right_version))
    if result:
        return result
    return _compare_prerelease(left_version.prerelease, right_version.prerelease)


def is_upgrade(current, candidate):
    """``candidate`` 是否严格高于 ``current``。"""
    return compare_versions(candidate, current) > 0
